import matplotlib.colors as mcolors
# Get the x-axis tick labels which correspond to the weeks
weeks = [float(t.get_text()) for t in ax.get_xticklabels()]
for i, patch in enumerate(ax.patches):
    if i < len(weeks) and weeks[i] >= 14:
        patch.set_color('#ff7f0e') # Orange for week >= 14
    else:
        patch.set_color('#1f77b4') # Blue for week < 14
